window.GOVAN_ENRICHMENT = {"version":"2026-11-26","subjects":{"geography":[{"id":"geography-1","title":"Weather and climate","level":"BGE","pairs":[["Weather","Atmospheric conditions over a short period"],["Climate","Long-term patterns in weather"],["Rain gauge","Instrument used to measure precipitation"],["Anemometer","Instrument used to measure wind speed"]],"application":{"q":"A cold day occurs during a warming trend. What can we conclude?","options":["One day alone cannot establish a climate trend","Global warming has stopped","Climate and weather mean exactly the same thing"],"answer":0,"why":"Climate concerns long-term patterns; a single observation is weather."},"challenge":"Describe what a month of temperature readings can show, and what it cannot establish about climate."},{"id":"geography-2","title":"Climate change","level":"BGE / Senior foundations","pairs":[["Mitigation","Action that reduces greenhouse gas emissions or increases their removal"],["Adaptation","Adjustment to actual or expected climate impacts"],["Greenhouse effect","Warming caused as certain gases absorb outgoing infrared radiation"],["Carbon sink","Store that takes in more carbon than it releases over a period"]],"application":{"q":"Which is primarily an adaptation to coastal flooding?","options":["Raising flood defences","Replacing coal electricity with wind","Insulating homes to cut energy use"],"answer":0,"why":"Defences reduce exposure to impacts. Cutting fossil-fuel use addresses a cause and is mitigation."},"challenge":"Explain how a city could combine one mitigation and one adaptation measure."},{"id":"geography-3","title":"Natural disasters","level":"BGE / Senior foundations","pairs":[["Hazard","Potentially damaging natural event or process"],["Risk","Likelihood and consequences of harm in a particular context"],["Vulnerability","Susceptibility of people or places to harm"],["Epicentre","Point on the surface directly above an earthquake focus"]],"application":{"q":"Why might similar earthquakes cause different losses?","options":["Exposure, vulnerability and preparedness differ","Magnitude alone fixes the number of deaths","Earthquake effects are identical everywhere"],"answer":0,"why":"Building quality, population exposure and response capacity influence impacts alongside physical characteristics."},"challenge":"Compare immediate relief with longer-term preparation for a named hazard."},{"id":"geography-4","title":"Physical environments: rivers and landscapes","level":"National 4–5 foundations","pairs":[["Erosion","Wearing away and removal of material"],["Transportation","Movement of eroded material"],["Deposition","Dropping of transported material"],["Watershed","Boundary separating drainage basins"]],"application":{"q":"A river loses velocity as it enters a loch. What is more likely?","options":["Deposition of some transported sediment","Every particle immediately dissolves","The drainage basin disappears"],"answer":0,"why":"Reduced energy can limit the sediment a river carries, encouraging deposition."},"challenge":"Use a labelled sketch to explain erosion and deposition at a meander."},{"id":"geography-5","title":"Human environments: population and settlement","level":"National 4–5 foundations","pairs":[["Population density","Number of people per unit area"],["Migration","Movement of people to live elsewhere"],["Urbanisation","Increase in the proportion of people living in urban areas"],["Dependency ratio","Comparison of dependent age groups with the working-age population"]],"application":{"q":"A population pyramid has a broad base. What is the strongest initial inference?","options":["A large proportion is in younger age groups","Everyone has a high income","There are no older people"],"answer":0,"why":"The base represents younger ages. Income and other conditions need additional evidence."},"challenge":"Explain two services a youthful population may need, using the pyramid as evidence."},{"id":"geography-6","title":"Environmental issues: land use and tourism","level":"National 4–5 / Higher foundations","pairs":[["Sustainability","Meeting present needs while protecting future capacity"],["Land-use conflict","Disagreement about how land should be used"],["Conservation","Protection and careful management of natural or cultural resources"],["Ecotourism","Tourism intended to support conservation and local communities"]],"application":{"q":"Which evidence best evaluates a tourism scheme?","options":["Environmental impacts alongside local income and residents’ views","Visitor numbers alone","The developer’s slogan alone"],"answer":0,"why":"Evaluation weighs competing outcomes, stakeholders and evidence rather than one attractive measure."},"challenge":"Recommend a response to visitor pressure and explain one trade-off."},{"id":"geography-7","title":"Higher geographical skills","level":"Higher foundations","pairs":[["Representative sample","Sample reflecting relevant characteristics of the wider group"],["Reliability","Consistency of a method or its results"],["Correlation","Association between variables"],["Anomaly","Observation that differs from the general pattern"]],"application":{"q":"A fieldwork survey samples only one street at noon. What is a key limitation?","options":["It may not represent other places or times","Every response must be dishonest","A larger font would remove sampling bias"],"answer":0,"why":"Restricted locations and times can systematically exclude relevant groups or conditions."},"challenge":"Design a better sampling approach and explain why correlation alone does not prove causation."}],"care":[{"id":"care-1","title":"Human development and behaviour","level":"Higher","pairs":[["Physical development","Changes in the body and physical abilities"],["Cognitive development","Changes in thinking and understanding"],["Emotional development","Changes in recognising and managing feelings"],["Social development","Changes in relationships and interaction"]],"application":{"q":"A fictional adult becomes isolated after moving home. Which response is most useful?","options":["Explore interacting social and emotional influences","Assume age alone explains everything","Treat each development strand as unrelated"],"answer":0,"why":"Development involves interacting factors; the individual’s circumstances and perspective matter."},"challenge":"Explain how a change in one development strand could influence two others in a fictional case."},{"id":"care-2","title":"Values and principles","level":"Higher","pairs":[["Dignity","Respect for a person’s inherent worth"],["Choice","Opportunity to make informed decisions"],["Confidentiality","Appropriate protection of personal information"],["Empowerment","Supporting a person’s control over their own life"]],"application":{"q":"A care worker decides everything without asking the person. What should improve?","options":["Support informed involvement and choice","Remove all information to avoid questions","Assume every person wants the same support"],"answer":0,"why":"Person-centred care involves the person in decisions with appropriate support and attention to needs."},"challenge":"Explain a potential tension between confidentiality and safeguarding using a fictional example and service procedures."},{"id":"care-3","title":"Social influences","level":"Higher","pairs":[["Socialisation","Learning norms, values and behaviours through social experience"],["Stereotype","Oversimplified generalisation about a group"],["Discrimination","Unfair treatment linked to a characteristic or group membership"],["Social inequality","Unequal distribution of resources, opportunities or outcomes"]],"application":{"q":"Two people have similar needs but different access to transport and income. Why consider this?","options":["Social circumstances can affect access to care","Care access depends only on personal motivation","Income determines every individual outcome"],"answer":0,"why":"Structural circumstances can create barriers; avoid assumptions about a person from one characteristic."},"challenge":"Link one social influence to a barrier, then explain how a service could reduce that barrier."}],"art":[{"id":"art-1","title":"Visual elements","level":"BGE / Senior foundations","pairs":[["Line","Mark or edge that can suggest direction and movement"],["Tone","Lightness or darkness"],["Texture","Actual or suggested surface quality"],["Composition","Arrangement of visual elements"]],"application":{"q":"A drawing looks flat. Which change most directly suggests three-dimensional form?","options":["Vary tone to reflect the light source","Make every area equally dark","Remove all differences between light and shade"],"answer":0,"why":"Tonal relationships can suggest form; the placement of highlights and shadows needs to fit the light."},"challenge":"Annotate three tonal decisions in your own study and explain their effects."},{"id":"art-2","title":"Expressive development","level":"BGE / National 4–5 foundations","pairs":[["Observation","Close looking used to inform visual recording"],["Primary source","First-hand visual information such as your own observational study"],["Development","Exploring and refining ideas through experiments"],["Evaluation","Judging strengths and improvements against intentions"]],"application":{"q":"Which sketchbook page best shows development?","options":["Experiments with annotations explaining decisions","Only a polished final image","Unrelated images without explanation"],"answer":0,"why":"Development reveals how choices evolve; annotations should connect experiments to intentions."},"challenge":"Choose two experiments and explain why one is more effective for your intended mood."},{"id":"art-3","title":"Design process","level":"National 4–5 / Higher foundations","pairs":[["Brief","Statement of a design problem and requirements"],["User","Person or group a design is intended to serve"],["Prototype","Test version used to explore a design"],["Constraint","Limit such as budget, material or size"]],"application":{"q":"A poster looks attractive but its date is hard to read. What should be prioritised?","options":["Improve hierarchy and readability for its audience","Add more decorative fonts","Make every word the same size"],"answer":0,"why":"Successful design meets communication needs as well as visual intentions."},"challenge":"Revise a poster for an audience with different access needs and justify the changes."},{"id":"art-4","title":"Critical study","level":"National 5 / Higher foundations","pairs":[["Context","Circumstances influencing the creation and interpretation of work"],["Technique","Method used to handle materials or create effects"],["Visual evidence","Specific observable features supporting an interpretation"],["Justification","Reasoned support for a judgement"]],"application":{"q":"Which comment is strongest?","options":["The compressed space and dark tones create tension because…","It is good because I like it","All viewers must feel exactly the same"],"answer":0,"why":"A supported interpretation names visual evidence and explains its effect; taste alone is not analysis."},"challenge":"Compare one compositional decision in two works and explain a similarity and a difference."}],"modern-studies":[{"id":"modern-studies-1","title":"Democracy in the UK","level":"National 5 foundations","pairs":[["Representative democracy","System where elected representatives make decisions"],["Constituency","Geographical area represented by an elected member"],["Manifesto","Published programme of a political party"],["Scrutiny","Examination of decisions and actions by those in power"]],"application":{"q":"Why is scrutiny important?","options":["It can require decision-makers to explain and justify actions","It guarantees every decision is popular","It removes the need for elections"],"answer":0,"why":"Accountability involves questioning power; scrutiny does not guarantee agreement or a particular result."},"challenge":"Explain two ways citizens can influence decisions beyond voting."},{"id":"modern-studies-2","title":"Terrorism","level":"National 5 foundations","pairs":[["Radicalisation","Process through which a person develops extremist views"],["Civil liberties","Basic freedoms protected in a society"],["International cooperation","Countries working together on shared problems"],["Evidence evaluation","Judging information for relevance, credibility and limitations"]],"application":{"q":"Which is the strongest way to assess a counter-terrorism policy?","options":["Weigh evidence of effectiveness against impacts on rights","Judge it only by a dramatic headline","Assume any restriction always succeeds"],"answer":0,"why":"Evaluation requires evidence and recognition of consequences. Avoid stereotyping communities or equating identity with extremism."},"challenge":"Explain a tension between public protection and civil liberties without assuming either aim can simply be ignored."},{"id":"modern-studies-3","title":"USA","level":"National 5 foundations","pairs":[["Federalism","Division of government power between national and state levels"],["Separation of powers","Division of functions among branches of government"],["Checks and balances","Arrangements allowing branches to limit one another"],["Participation","Involvement in political processes"]],"application":{"q":"Why distinguish state and federal responsibilities?","options":["Rules and decisions can operate at different levels","All states have identical policy choices","State governments replace the national government"],"answer":0,"why":"Federal systems distribute powers; the level responsible matters when explaining policy and participation."},"challenge":"Explain how one barrier can affect participation and identify evidence you would need to assess its impact."},{"id":"modern-studies-4","title":"Crime and law","level":"National 5 foundations","pairs":[["Deterrence","Aim of discouraging offending through consequences"],["Rehabilitation","Support intended to reduce future offending"],["Reoffending","Further offending after a previous offence or sanction"],["Victim support","Practical or emotional assistance for people affected by crime"]],"application":{"q":"A programme reports fewer reconvictions among participants. What else should be checked?","options":["Comparison group, follow-up period and participant selection","Only the programme logo","Whether every participant has the same first name"],"answer":0,"why":"An apparent improvement needs a fair comparison and attention to alternative explanations."},"challenge":"Compare rehabilitation and deterrence as aims of a response to crime."},{"id":"modern-studies-5","title":"Democracy in Scotland","level":"Higher foundations","pairs":[["Devolution","Transfer of specified powers to a lower level of government"],["Reserved matter","Area retained at UK level under the devolution settlement"],["Proportional representation","Electoral approach intended to relate seats to votes"],["Pressure group","Organisation seeking to influence policy on particular issues"]],"application":{"q":"Why might a voting system affect representation?","options":["Methods of translating votes into seats differ","Voting systems determine every voter’s opinion","Every system always produces the same seats"],"answer":0,"why":"Electoral rules influence outcomes and representation, alongside voter preferences and political context."},"challenge":"Evaluate one method of participation, considering both its influence and limitations."},{"id":"modern-studies-6","title":"Social inequality","level":"Higher foundations","pairs":[["Relative poverty","Low resources compared with the society in which someone lives"],["Structural factor","Influence arising from institutions or wider social conditions"],["Redistribution","Changing the distribution of resources through policies"],["Intersection","Interaction of different social positions or disadvantages"]],"application":{"q":"An area has poorer average health and lower incomes. What can this alone establish?","options":["An association that needs further explanation","Proof that low income is the only cause","That every resident has the same health"],"answer":0,"why":"Area averages and associations do not establish every individual’s experience or a single causal explanation."},"challenge":"Evaluate a policy using evidence on both outcomes and who benefits."},{"id":"modern-studies-7","title":"South Africa","level":"Higher foundations","pairs":[["Apartheid","Former system of legally enforced racial segregation and domination"],["Constitution","Framework setting out government structures and fundamental rights"],["Inequality","Unequal distribution of resources or opportunities"],["Service delivery","Provision of public services to communities"]],"application":{"q":"Why combine national statistics with local evidence?","options":["National averages can conceal differences between communities","Local evidence always represents the whole country","Statistics never contribute to an explanation"],"answer":0,"why":"Multiple scales help explain variation; consider reliability, dates and how indicators are defined."},"challenge":"Explain how historical and contemporary factors may interact in one inequality; use dated evidence."},{"id":"modern-studies-8","title":"Sources and conclusions","level":"BGE / Senior foundations","pairs":[["Fact","Claim that can be checked against evidence"],["Opinion","Judgement or viewpoint"],["Selective use","Choosing evidence while overlooking relevant contrary information"],["Supported conclusion","Judgement linked explicitly to relevant evidence"]],"application":{"q":"Two sources disagree. What should you do first?","options":["Check what each measures, its date and its evidence","Choose the most colourful one","Assume disagreement makes both useless"],"answer":0,"why":"Differences may reflect method, scope, time or perspective; investigate before drawing a conclusion."},"challenge":"Write a conclusion that uses two pieces of evidence and acknowledges a limitation."}],"maths":[{"id":"maths-1","title":"Number, percentages and finance","level":"BGE / National 4–5 foundations","pairs":[["Percentage","Number of parts per hundred"],["Multiplier","Factor used to scale a quantity"],["Interest","Charge or return calculated on money"],["Unit price","Cost for one standard unit"]],"application":{"q":"A £60 item is reduced by 20%. What is the sale price?","options":["£48","£40","£12"],"answer":0,"why":"20% of £60 is £12; subtracting gives £48. £12 is the saving, not the price."},"challenge":"Explain why a 20% decrease followed by a 20% increase does not return to the original value."},{"id":"maths-2","title":"Expressions and formulae","level":"National 4–5 foundations","pairs":[["Coefficient","Numerical factor multiplying a variable"],["Like terms","Terms with identical variable parts and powers"],["Substitution","Replacing a variable with a value"],["Expansion","Removing brackets by multiplication"]],"application":{"q":"Simplify 3x + 2x − 4.","options":["5x − 4","5x − 20","x − 4"],"answer":0,"why":"The x terms combine to 5x; the constant remains −4."},"challenge":"Explain the difference between simplifying an expression and solving an equation."},{"id":"maths-3","title":"Relationships and equations","level":"National 4–5 foundations","pairs":[["Equation","Statement that two expressions are equal"],["Solution","Value making an equation true"],["Gradient","Rate of change in y for a unit change in x"],["Intercept","Point at which a graph meets an axis"]],"application":{"q":"Solve 2x + 3 = 11.","options":["x = 4","x = 7","x = 14"],"answer":0,"why":"Subtract 3 to get 2x = 8, then divide by 2. Check by substituting 4."},"challenge":"Find two points on y = 2x + 1 and explain how its gradient appears on a graph."},{"id":"maths-4","title":"Geometry and trigonometry","level":"National 4–5 foundations","pairs":[["Hypotenuse","Longest side of a right-angled triangle, opposite the right angle"],["Perimeter","Distance around a shape"],["Area","Measure of a two-dimensional region"],["Volume","Measure of three-dimensional space"]],"application":{"q":"A right-angled triangle has shorter sides 3 cm and 4 cm. Find its hypotenuse.","options":["5 cm","7 cm","25 cm"],"answer":0,"why":"Pythagoras gives c² = 9 + 16 = 25, so c = 5 cm."},"challenge":"Explain when Pythagoras is appropriate and why you must identify the right angle first."},{"id":"maths-5","title":"Statistics and probability","level":"BGE / National 4–5 foundations","pairs":[["Mean","Sum of values divided by their number"],["Median","Middle value after ordering the data"],["Range","Largest value minus smallest value"],["Probability","Measure of how likely an event is"]],"application":{"q":"Find the median of 2, 3, 4, 5, 26.","options":["4","8","24"],"answer":0,"why":"The ordered list has five values, so its third value is the median. The mean is 8 and the range is 24."},"challenge":"Explain which average is more informative when an unusually large value is present."},{"id":"maths-6","title":"Functions and calculus","level":"Higher foundations","pairs":[["Derivative","Function describing instantaneous rate of change"],["Stationary point","Point where the derivative is zero"],["Composite function","Function applied to the output of another function"],["Definite integral","Signed area under a curve between limits"]],"application":{"q":"Differentiate f(x) = x³.","options":["f′(x) = 3x²","f′(x) = x²","f′(x) = 3x³"],"answer":0,"why":"Use the power rule: multiply by the power and reduce the power by one."},"challenge":"For f(x) = x² − 4x, find a stationary point and explain how you would classify it."}],"english":[{"id":"english-1","title":"Reading for understanding","level":"BGE / National 4–5 foundations","pairs":[["Main idea","Central point developed in a text"],["Inference","Conclusion drawn from clues and knowledge"],["Evidence","Specific detail supporting an interpretation"],["Summary","Concise account of the main points"]],"application":{"q":"A character grips a ticket and repeatedly checks the clock. What is a reasonable inference?","options":["They may be anxious about time or travel","They definitely dislike every journey","They must be the station manager"],"answer":0,"why":"The actions suggest possible anxiety; an inference should be supported without claiming more certainty than the text allows."},"challenge":"Write an inference, quote a short supporting detail and explain the connection."},{"id":"english-2","title":"Language analysis","level":"National 5 / Higher foundations","pairs":[["Connotation","Associated meaning or suggestion of a word"],["Simile","Comparison using like or as"],["Metaphor","Description presenting one thing as another"],["Contrast","Placement of differences together for effect"]],"application":{"q":"What is most useful after identifying a metaphor?","options":["Explain how its comparison shapes meaning in context","List more technique names without explanation","Claim all metaphors have the same effect"],"answer":0,"why":"Analysis explains how a particular choice creates meaning; naming a device is only a starting point."},"challenge":"Create an original metaphor, then explain the qualities being compared and the intended effect."},{"id":"english-3","title":"Critical essay","level":"National 5 / Higher foundations","pairs":[["Thesis","Main argument of an essay"],["Topic sentence","Sentence establishing a paragraph’s main focus"],["Analysis","Explanation of how details create meaning or effects"],["Evaluation","Supported judgement about significance or effectiveness"]],"application":{"q":"Which paragraph best supports an essay argument?","options":["A focused claim, relevant textual evidence and explained links to the question","Plot summary with no connection to the question","A quotation followed only by “this is effective”"],"answer":0,"why":"An analytical paragraph connects evidence and explanation to the argument rather than simply retelling events."},"challenge":"Plan a paragraph on a text you study: claim, evidence, explanation and link to the essay question."},{"id":"english-4","title":"Writing, listening and talking","level":"BGE / Senior foundations","pairs":[["Audience","People a text or talk is intended for"],["Purpose","What a communication aims to achieve"],["Register","Level and style of language suited to a situation"],["Editing","Revising content and expression to improve a piece"]],"application":{"q":"How should a speech to younger pupils differ from a technical report?","options":["Use accessible explanations suited to its audience and purpose","Remove every fact","Use the longest words available"],"answer":0,"why":"Effective communication adapts detail, tone and structure to its listeners or readers."},"challenge":"Rewrite one paragraph for a different audience, then explain two changes."}],"spanish":[{"id":"spanish-1","title":"Society: identity and family","level":"BGE / National 4–5 foundations","pairs":[["Me llamo","My name is"],["Tengo","I have"],["Soy","I am, for identity or a characteristic"],["Hay","There is or there are"]],"application":{"q":"Choose “I am fifteen years old”.","options":["Tengo quince años","Soy quince años","Hay quince años"],"answer":0,"why":"Spanish expresses age with tener: tengo quince años. It does not use soy for age."},"challenge":"Introduce a fictional person with their name, age and two details; avoid sharing personal information."},{"id":"spanish-2","title":"Learning: school","level":"BGE / National 4–5 foundations","pairs":[["Estudio","I study"],["Aprendo","I learn"],["La asignatura","The school subject"],["El horario","The timetable"]],"application":{"q":"Choose “I like history because it is interesting”.","options":["Me gusta la historia porque es interesante","Me gustan la historia porque es interesante","Soy historia interesante"],"answer":0,"why":"A singular subject uses me gusta; porque introduces a reason."},"challenge":"Give an opinion about two subjects and justify each with a different reason."},{"id":"spanish-3","title":"Employability: future plans","level":"National 5 / Higher foundations","pairs":[["Quisiera","I would like"],["Voy a estudiar","I am going to study"],["El trabajo","The job or work"],["Las prácticas","Work experience or practical placements"]],"application":{"q":"Choose “I am going to work”.","options":["Voy a trabajar","Voy trabajar","Soy a trabajar"],"answer":0,"why":"The near future uses ir + a + infinitive: voy a trabajar."},"challenge":"Describe a fictional future plan, give a reason and include one skill you want to develop."},{"id":"spanish-4","title":"Culture: travel and experiences","level":"National 5 / Higher foundations","pairs":[["Fui","I went, in the preterite"],["Visité","I visited"],["Me gustaría","I would like"],["El alojamiento","Accommodation"]],"application":{"q":"Which phrase clearly refers to a completed past visit?","options":["El año pasado visité Madrid","El año que viene visitaré Madrid","Ahora vivo en Madrid"],"answer":0,"why":"El año pasado and visité locate the visit in the past; the other options refer to the future or present."},"challenge":"Compare a past holiday with a future travel preference using clear time markers."}],"french":[{"id":"french-1","title":"Society: identity and relationships","level":"BGE / National 4–5 foundations","pairs":[["Je m’appelle","My name is"],["J’ai","I have"],["Je suis","I am"],["Il y a","There is or there are"]],"application":{"q":"Choose “I am fourteen years old”.","options":["J’ai quatorze ans","Je suis quatorze ans","Il y a quatorze ans"],"answer":0,"why":"French uses avoir to state age: j’ai quatorze ans."},"challenge":"Introduce a fictional person, including age and two characteristics, checking adjective agreement."},{"id":"french-2","title":"Learning: school","level":"BGE / National 4–5 foundations","pairs":[["J’étudie","I study"],["J’apprends","I learn"],["L’emploi du temps","The timetable"],["Les devoirs","Homework"]],"application":{"q":"Choose “I like maths because it is useful”.","options":["J’aime les maths parce que c’est utile","Je suis les maths utile","J’ai maths parce utile"],"answer":0,"why":"J’aime expresses the preference and parce que introduces a reason."},"challenge":"Give two opinions about school and support each with a reason; practise saying them clearly."},{"id":"french-3","title":"Employability: ambitions","level":"National 5 / Higher foundations","pairs":[["Je voudrais","I would like"],["Je vais travailler","I am going to work"],["Un emploi","A job"],["Un stage","A work placement"]],"application":{"q":"Which phrase means “I am going to study”?","options":["Je vais étudier","Je vais étudié","J’ai étudier"],"answer":0,"why":"The near future is aller + infinitive. Étudier remains in its infinitive form."},"challenge":"Explain a fictional career ambition and a skill that would help, including a future tense."},{"id":"french-4","title":"Culture: travel and past events","level":"National 5 / Higher foundations","pairs":[["J’ai visité","I visited"],["Je suis allé","I went, with a masculine speaker"],["L’hébergement","Accommodation"],["L’année prochaine","Next year"]],"application":{"q":"Which sentence describes a completed visit?","options":["L’année dernière, j’ai visité Paris","L’année prochaine, je visiterai Paris","En ce moment, je visite Paris"],"answer":0,"why":"L’année dernière and the perfect tense indicate a past visit; the alternatives point to future or current activity."},"challenge":"Compare a previous visit with a future plan, adjusting agreement where needed."}],"history":[{"id":"history-1","title":"Govan: work and change","level":"Suggested BGE / skills","pairs":[["Primary source","Evidence originating from the period or event being studied"],["Secondary account","Later interpretation of events"],["Continuity","Feature that remains broadly similar over time"],["Change","Difference between periods or conditions"]],"application":{"q":"What best investigates changing working conditions?","options":["Compare dated workers’ accounts, inspection evidence and employment records","Use one undated photograph alone","Assume all workers had identical experiences"],"answer":0,"why":"Different dated sources can illuminate experience and change; one image cannot establish the full pattern."},"challenge":"Explain one change and one continuity using two dated pieces of evidence."},{"id":"history-2","title":"Power and protest","level":"Suggested BGE / Senior skills","pairs":[["Cause","Factor contributing to an event or development"],["Consequence","Effect resulting from an event or development"],["Short-term factor","Influence operating relatively close to an event"],["Long-term factor","Influence developing over an extended period"]],"application":{"q":"A protest follows years of hardship and a new unpopular measure. Which explanation is strongest?","options":["The measure may trigger action within longer-term conditions","Only events on the final day matter","Long-term conditions make triggers irrelevant"],"answer":0,"why":"Historical explanation considers interactions between underlying conditions and more immediate triggers."},"challenge":"Rank two causes of a studied event, explaining their relationship rather than only listing them."},{"id":"history-3","title":"Source evaluation","level":"National 5 / Higher foundations","pairs":[["Provenance","Origin, authorship and circumstances of a source"],["Purpose","What the creator intended a source to achieve"],["Corroboration","Support from other independent evidence"],["Limitation","Reason a source cannot fully answer an enquiry"]],"application":{"q":"An official recruitment poster praises military life. How should it be used?","options":["As evidence of recruitment messages, checked against other experiences","As a complete neutral description of all military life","As completely worthless because it is persuasive"],"answer":0,"why":"Purpose affects usefulness for a particular enquiry; propaganda can still reveal messages and priorities."},"challenge":"Evaluate a source for a precise enquiry, using provenance, content and relevant contextual knowledge."},{"id":"history-4","title":"Explaining and evaluating historical issues","level":"National 5 / Higher skills","pairs":[["Argument","Reasoned position developed in response to a question"],["Contextual knowledge","Relevant knowledge of the period beyond the source"],["Judgement","Supported decision about significance or extent"],["Historical interpretation","Explanation of the past based on selected evidence"]],"application":{"q":"What makes a historical conclusion stronger?","options":["Weighing relevant factors and answering the exact question","Repeating the introduction word for word","Adding an unsupported new claim"],"answer":0,"why":"A conclusion draws together evidence and relative importance to support a clear judgement."},"challenge":"Choose a taught Scottish, British or world context and explain why one factor mattered more than another."}],"rme":[{"id":"rme-1","title":"Beliefs and worldviews","level":"BGE / RMPS foundations","pairs":[["Worldview","Framework through which someone understands life and meaning"],["Religious belief","Conviction connected to a religious tradition or understanding"],["Non-religious worldview","Outlook not based on religious belief"],["Diversity","Variation within and between groups"]],"application":{"q":"Which statement is most careful?","options":["People within the same tradition can interpret and practise differently","Every believer holds identical views","One individual represents an entire worldview"],"answer":0,"why":"Avoid treating a tradition as uniform; investigate both shared teachings and differences in interpretation."},"challenge":"Compare two viewpoints fairly, identifying both a similarity and a difference."},{"id":"rme-2","title":"Morality and reasoning","level":"BGE / RMPS foundations","pairs":[["Moral claim","Judgement about right, wrong or responsibility"],["Consequence","Outcome of an action"],["Duty","Obligation someone believes should guide action"],["Justification","Reasons offered in support of a view"]],"application":{"q":"Two people disagree about an ethical decision. What helps discussion?","options":["Clarify their reasons, assumptions and possible consequences","Dismiss the person with a different view","Replace reasons with a louder voice"],"answer":0,"why":"Ethical discussion examines the reasoning behind claims while respecting people."},"challenge":"Evaluate a fictional dilemma from both a duty-based and an outcome-based perspective."},{"id":"rme-3","title":"Religion, society and justice","level":"BGE / RMPS foundations","pairs":[["Prejudice","Preconceived judgement about a person or group"],["Discrimination","Unfair treatment related to a characteristic or group"],["Equality","Equal worth and entitlement to fair treatment"],["Equity","Support adjusted to reduce unequal barriers"]],"application":{"q":"Giving everyone the same resource leaves some unable to access a task. What may improve fairness?","options":["Provide suitable support addressing different barriers","Assume identical treatment always produces fair access","Exclude anyone needing an adjustment"],"answer":0,"why":"Equal worth can require different support to enable participation; identify the barrier rather than make assumptions."},"challenge":"Explain how a community could protect freedom of belief while challenging discrimination."},{"id":"rme-4","title":"Questions, sources and evaluation","level":"National 5 / Higher RMPS skills","pairs":[["Premise","Statement used as a reason in an argument"],["Conclusion","Claim an argument seeks to support"],["Counterargument","Reasoned challenge to an argument"],["Consistency","Compatibility of claims within a position"]],"application":{"q":"An argument has a confident conclusion but no supporting reasons. What is missing?","options":["A justification connecting evidence or premises to the claim","A more dramatic heading","Agreement from everyone"],"answer":0,"why":"Confidence does not establish validity or truth; reasons and assumptions need examination."},"challenge":"Build an argument and a serious counterargument, then explain your final judgement."}],"chemistry":[{"id":"chemistry-1","title":"Particles, atoms and bonding","level":"BGE / National 4–5 foundations","pairs":[["Proton","Positively charged particle in the nucleus"],["Electron","Negatively charged particle outside the nucleus"],["Ion","Atom or group of atoms with an overall charge"],["Covalent bond","Bond formed by a shared pair of electrons"]],"application":{"q":"A neutral atom loses one electron. What forms?","options":["A positive ion","A negative ion","A different element because its proton number changes"],"answer":0,"why":"Losing negative charge leaves a net positive charge. Proton number remains unchanged."},"challenge":"Explain ionic bonding using electron transfer and electrostatic attraction as distinct steps."},{"id":"chemistry-2","title":"Acids, alkalis and neutralisation","level":"BGE / National 4–5 foundations","pairs":[["Acid","Substance producing hydrogen ions in aqueous solution"],["Alkali","Soluble base producing hydroxide ions in aqueous solution"],["Neutralisation","Reaction of an acid with a base"],["Indicator","Substance showing different colours in different pH conditions"]],"application":{"q":"An acid reacts with a metal carbonate. Which gas is produced?","options":["Carbon dioxide","Hydrogen","Oxygen"],"answer":0,"why":"Acid + metal carbonate produces a salt, water and carbon dioxide. Acid + many metals instead gives hydrogen."},"challenge":"Predict products for an acid–alkali reaction and explain how an indicator helps monitor it; do no practical work without teacher instructions."},{"id":"chemistry-3","title":"Nature’s chemistry: carbon compounds","level":"National 5 foundations","pairs":[["Hydrocarbon","Compound containing only hydrogen and carbon"],["Homologous series","Family with a common general formula and similar chemical properties"],["Saturated","Containing only single carbon–carbon bonds"],["Alcohol","Compound containing a hydroxyl group attached to a saturated carbon atom"]],"application":{"q":"Which formula represents an alkane?","options":["C₃H₈","C₃H₆","CO₂"],"answer":0,"why":"Alkanes follow CnH2n+2; for n = 3 this is C₃H₈."},"challenge":"Compare an alkane and an alkene in bonding and a suitable test, as a written explanation only."},{"id":"chemistry-4","title":"Chemistry in society: materials and energy","level":"BGE / National 5 foundations","pairs":[["Ore","Rock containing enough useful material for economic extraction"],["Electrolysis","Decomposition of an ionic substance using electricity"],["Polymer","Large molecule made from repeating small units"],["Life-cycle assessment","Evaluation of environmental impacts across a product’s life"]],"application":{"q":"Why is recycling a metal sometimes less energy-intensive than extraction?","options":["Some processing of the ore and chemical extraction can be avoided","Recycling always needs no energy","Atoms are created during recycling"],"answer":0,"why":"Recycling still uses energy, but can avoid energy-demanding extraction steps. The comparison depends on the material and process."},"challenge":"Compare two packaging materials across production, use and disposal rather than one impact alone."},{"id":"chemistry-5","title":"Chemical changes and structure","level":"Higher foundations","pairs":[["Activation energy","Minimum energy required for a successful reaction event"],["Catalyst","Substance offering an alternative reaction pathway with lower activation energy"],["Electronegativity","Attraction of an atom for bonding electrons"],["Collision theory","Model relating reaction rate to successful particle collisions"]],"application":{"q":"How does a catalyst increase rate?","options":["It lowers activation energy through an alternative pathway","It increases the energy change between reactants and products","It is used up as the main reactant"],"answer":0,"why":"A catalyst changes the pathway, not the overall enthalpy change, and is regenerated overall."},"challenge":"Sketch a labelled energy profile with and without a catalyst."}],"physics":[{"id":"physics-1","title":"Motion and forces","level":"BGE / National 4–5 foundations","pairs":[["Speed","Distance travelled per unit time"],["Velocity","Displacement per unit time in a specified direction"],["Acceleration","Rate of change of velocity"],["Resultant force","Single force equivalent to the combined forces"]],"application":{"q":"A car travels 150 m in 10 s. Find its average speed.","options":["15 m/s","1,500 m/s","0.067 m/s"],"answer":0,"why":"Average speed = distance ÷ time = 150 ÷ 10 = 15 m/s."},"challenge":"Explain why zero resultant force does not necessarily mean an object is at rest."},{"id":"physics-2","title":"Electricity","level":"National 4–5 foundations","pairs":[["Current","Rate of flow of electric charge"],["Potential difference","Energy transferred per unit charge"],["Resistance","Ratio of potential difference to current"],["Series circuit","Circuit with one path for current"]],"application":{"q":"A resistor has 6 V across it and current 2 A. Find its resistance.","options":["3 Ω","12 Ω","0.33 Ω"],"answer":0,"why":"R = V/I = 6/2 = 3 Ω."},"challenge":"Explain why current is the same through components in one series loop; follow teacher rules for practical circuits."},{"id":"physics-3","title":"Waves and radiation","level":"BGE / National 5 foundations","pairs":[["Frequency","Number of complete oscillations per second"],["Wavelength","Distance between corresponding points on adjacent waves"],["Amplitude","Maximum displacement from equilibrium"],["Ionisation","Removal or addition of electrons, producing charged particles"]],"application":{"q":"A wave has frequency 5 Hz and wavelength 2 m. Find speed.","options":["10 m/s","2.5 m/s","0.4 m/s"],"answer":0,"why":"v = fλ = 5 × 2 = 10 m/s."},"challenge":"Explain the difference between increasing frequency and increasing amplitude."},{"id":"physics-4","title":"Energy and heat","level":"BGE / National 4–5 foundations","pairs":[["Kinetic energy","Energy associated with motion"],["Power","Rate of energy transfer"],["Efficiency","Useful output energy divided by total input energy"],["Specific heat capacity","Energy needed to raise the temperature of one kilogram by one degree"]],"application":{"q":"A device transfers 600 J in 20 s. Find its power.","options":["30 W","12,000 W","0.033 W"],"answer":0,"why":"P = E/t = 600/20 = 30 W."},"challenge":"Draw an energy-transfer diagram and explain why efficiency is not usually 100%."},{"id":"physics-5","title":"Our dynamic universe","level":"Higher foundations","pairs":[["Momentum","Mass multiplied by velocity"],["Impulse","Change in momentum"],["Projectile","Object moving under gravity after launch, with air resistance often neglected"],["Vector","Quantity with magnitude and direction"]],"application":{"q":"Why does an airbag reduce average force for the same momentum change?","options":["It increases the time over which the change occurs","It removes the passenger’s initial momentum","It makes the momentum change take zero time"],"answer":0,"why":"Average force = change in momentum ÷ time. A longer stopping time reduces average force for a fixed change."},"challenge":"Explain the independence of horizontal and vertical motion in the ideal projectile model."}],"biology":[{"id":"biology-1","title":"Cell biology","level":"National 4–5 foundations","pairs":[["Diffusion","Net movement of particles down a concentration gradient"],["Osmosis","Net movement of water across a selectively permeable membrane down a water concentration gradient"],["Enzyme","Biological catalyst"],["Respiration","Cellular reactions releasing energy from a substrate"]],"application":{"q":"Why can high temperature reduce enzyme activity?","options":["It can alter the active site through denaturation","It always creates more active sites","It removes the need for a substrate"],"answer":0,"why":"Denaturation changes protein structure so a substrate may no longer fit the active site."},"challenge":"Compare diffusion and active transport, including direction and energy requirements."},{"id":"biology-2","title":"Multicellular organisms","level":"National 4–5 foundations","pairs":[["Tissue","Group of similar cells working together"],["Organ","Structure made from different tissues performing functions"],["Homeostasis","Maintenance of internal conditions within suitable limits"],["Hormone","Chemical messenger carried to target tissues"]],"application":{"q":"After blood glucose rises, which hormone helps lower it?","options":["Insulin","Adrenaline in every situation","Glucagon"],"answer":0,"why":"Insulin promotes uptake of glucose and storage as glycogen; glucagon acts to increase blood glucose when needed."},"challenge":"Explain why negative feedback helps maintain a stable internal environment."},{"id":"biology-3","title":"Life on Earth","level":"BGE / National 4–5 foundations","pairs":[["Producer","Organism making organic substances from inorganic materials"],["Consumer","Organism obtaining energy by eating other organisms"],["Biodiversity","Variety of living organisms in an area or system"],["Competition","Interaction over limited resources"]],"application":{"q":"In grass → rabbit → fox, what do the arrows represent?","options":["Direction of energy transfer","Which animal is largest","The direction animals prefer to travel"],"answer":0,"why":"Food-chain arrows point from a food source to the organism obtaining energy from it."},"challenge":"Predict one possible effect of a rabbit decline, and explain why a food web gives more information than a single chain."},{"id":"biology-4","title":"DNA and the genome","level":"Higher foundations","pairs":[["Gene","DNA sequence contributing to a functional product"],["Transcription","Production of RNA using a DNA template"],["Translation","Assembly of a polypeptide using information in mRNA"],["Mutation","Change in genetic material"]],"application":{"q":"A base substitution occurs in a coding sequence. Is the protein always changed?","options":["No; the genetic code is degenerate and effects vary","Yes; every substitution changes every amino acid","No mutation can ever affect a protein"],"answer":0,"why":"Different codons can specify the same amino acid; effects depend on the mutation and its position."},"challenge":"Trace information from DNA to a polypeptide, identifying where complementary base pairing is involved."},{"id":"biology-5","title":"Metabolism and survival","level":"Higher foundations","pairs":[["Metabolic pathway","Linked series of enzyme-controlled reactions"],["ATP","Immediate energy-transfer molecule used in cells"],["Feedback inhibition","End product reducing activity earlier in its pathway"],["Adaptation","Inherited feature contributing to survival or reproduction in a particular environment"]],"application":{"q":"Why is feedback inhibition useful?","options":["It can prevent unnecessary production of an end product","It guarantees enzymes work without substrates","It permanently destroys all pathway enzymes"],"answer":0,"why":"Regulation helps coordinate demand, resources and energy use without requiring permanent enzyme destruction."},"challenge":"Explain how changing conditions can affect metabolic activity and survival."},{"id":"biology-6","title":"Sustainability and interdependence","level":"Higher foundations","pairs":[["Carrying capacity","Population size an environment can sustain over time"],["Selection pressure","Environmental influence affecting relative reproductive success"],["Food security","Reliable access to sufficient safe and nutritious food"],["Integrated pest management","Combined approaches to controlling pests with reduced reliance on one method"]],"application":{"q":"Why might repeated use of one pesticide become less effective?","options":["Resistant variants can leave more offspring","Every pest chooses to become resistant","Pesticides directly teach all pests to adapt"],"answer":0,"why":"Selection acts on variation; resistant organisms may survive and reproduce, changing population composition."},"challenge":"Weigh a food-production method against biodiversity and resource use."},{"id":"biology-7","title":"Human biology: health and immunity","level":"Higher Human Biology foundations","pairs":[["Antigen","Molecule recognised by the immune system"],["Antibody","Protein binding specifically to an antigen"],["Memory cell","Long-lived immune cell supporting a faster response on re-exposure"],["Vaccination","Stimulation of an immune response and memory without the full disease"]],"application":{"q":"Why can a secondary immune response be faster?","options":["Memory cells respond to a previously encountered antigen","Antibiotics are stored in every memory cell","All pathogens become harmless after one infection"],"answer":0,"why":"Immune memory supports a faster specific response; protection varies and is not a guarantee against all infection."},"challenge":"Distinguish innate and adaptive defences and explain why specificity matters."}],"esol":[{"id":"esol-1","title":"Everyday communication","level":"BGE / early ESOL practice","pairs":[["Greeting","Words used to begin a social exchange"],["Clarification","Checking or explaining something unclear"],["Request","Polite expression asking for something"],["Instruction","Direction telling someone what to do"]],"application":{"q":"You did not understand a classroom instruction. What is useful?","options":["Could you say that again, please?","Pretend you understood every word","Leave without asking"],"answer":0,"why":"A polite clarification request helps communication and gives the speaker a chance to rephrase."},"challenge":"Practise asking for repetition, slower speech and an example in a short role-play."},{"id":"esol-2","title":"Reading for information","level":"National 3–5 foundations","pairs":[["Heading","Title identifying a section’s topic"],["Key word","Word central to the information needed"],["Skimming","Reading quickly for overall meaning"],["Scanning","Looking for a specific detail"]],"application":{"q":"You need a bus departure time from a timetable. Which approach fits best?","options":["Scan the relevant route and time column","Read every word of an unrelated leaflet","Guess from the colour of the page"],"answer":0,"why":"Scanning is useful for precise information; checking headings prevents confusion between routes or days."},"challenge":"Read a supplied timetable and explain how you checked the right route, day and direction."},{"id":"esol-3","title":"Writing for purpose","level":"National 3–5 foundations","pairs":[["Audience","Intended reader"],["Formal register","Language suited to a professional or official situation"],["Paragraph","Group of sentences developing a related point"],["Proofreading","Checking a text for errors before sharing"]],"application":{"q":"Which opening fits a formal request to an organisation?","options":["Dear Sir or Madam, I am writing to ask…","Hey mate!!!","No greeting or purpose at all"],"answer":0,"why":"Formal language makes the relationship and purpose clear. A named recipient is preferable when available."},"challenge":"Write a short fictional enquiry including purpose, one question and an appropriate closing."},{"id":"esol-4","title":"Study and work conversations","level":"National 5 / Higher foundations","pairs":[["Main point","Central message of a contribution"],["Turn-taking","Sharing opportunities to speak and listen"],["Paraphrase","Restatement using different words"],["Supporting detail","Information explaining or illustrating a main point"]],"application":{"q":"How can you check you understood a colleague?","options":["So, do you mean that…?","Interrupt repeatedly before they finish","Repeat one word without checking its meaning"],"answer":0,"why":"A checking paraphrase allows correction and shows active listening."},"challenge":"Give an opinion, a reason and an example, then invite another person’s view."}],"graphic-communication":[{"id":"graphic-communication-1","title":"Drawing conventions","level":"BGE / National 4–5 foundations","pairs":[["Orthographic projection","Related two-dimensional views representing a three-dimensional object"],["Plan","View from above"],["Elevation","View of a vertical face"],["Hidden detail","Edges not directly visible in a view"]],"application":{"q":"Why align related orthographic views?","options":["So features can be read consistently across the views","To make every view identical","To remove the need for dimensions"],"answer":0,"why":"Alignment helps communicate positions and relationships; different views show different faces."},"challenge":"Sketch a simple object in plan and two elevations, checking alignment and dimensions."},{"id":"graphic-communication-2","title":"Pictorial graphics and CAD","level":"National 5 foundations","pairs":[["Isometric view","Pictorial view with three principal axes equally inclined in projection"],["CAD","Computer-aided design"],["Extrusion","Creation of a solid by extending a two-dimensional profile"],["Fillet","Rounded transition between surfaces or edges"]],"application":{"q":"A rectangle is extruded perpendicular to its plane. What is produced?","options":["A rectangular prism","A sphere","A flat line with no volume"],"answer":0,"why":"Extrusion extends the area through a depth, giving a solid with a constant cross-section."},"challenge":"Explain when a pictorial view communicates better than a single orthographic view."},{"id":"graphic-communication-3","title":"Design and layout","level":"National 5 / Higher foundations","pairs":[["Hierarchy","Arrangement directing attention to the most important information"],["Contrast","Difference helping elements stand apart"],["Alignment","Placement along common lines or edges"],["White space","Unoccupied area used to organise a layout"]],"application":{"q":"A poster has five equally dominant headings. What might improve it?","options":["Establish a clear reading order through hierarchy","Add five more competing headings","Remove all spacing"],"answer":0,"why":"Hierarchy guides the viewer; size, contrast and spacing can communicate priority."},"challenge":"Redesign a poster for viewing on an iPad, explaining three layout choices."},{"id":"graphic-communication-4","title":"Production and evaluation","level":"National 5 / Higher foundations","pairs":[["Specification","Detailed requirements for a graphic product"],["Accuracy","Closeness to intended dimensions or information"],["Rendering","Adding visual appearance such as tone, colour and material effects"],["Evaluation","Judging success against stated requirements"]],"application":{"q":"A rendered image is attractive but lacks a critical dimension. What is the issue?","options":["It may fail its technical communication purpose","Rendering automatically guarantees technical accuracy","Dimensions never matter if colour is used"],"answer":0,"why":"Graphic quality depends on purpose. A production drawing must communicate required technical information."},"challenge":"Evaluate a graphic against audience, accuracy and presentation rather than appearance alone."}],"woodwork":[{"id":"woodwork-1","title":"Measuring and marking","level":"BGE / National 4–5 foundations","pairs":[["Face side","Chosen reference surface for marking and working"],["Try square","Tool for checking and marking a right angle"],["Marking gauge","Tool for marking a line parallel to an edge"],["Tolerance","Permitted variation from a specified dimension"]],"application":{"q":"Why use a consistent reference face?","options":["To reduce accumulated marking and alignment errors","To avoid checking measurements","To make every piece the same shape"],"answer":0,"why":"A stable reference makes separate measurements relate consistently to one another."},"challenge":"Describe a marking-out sequence and two checks before cutting; practical work requires teacher supervision."},{"id":"woodwork-2","title":"Flat-frame joints","level":"National 4–5 foundations","pairs":[["Mortise","Recess made to receive a tenon"],["Tenon","Projecting part fitting into a mortise"],["Dowel","Cylindrical piece used to locate or join components"],["Dry assembly","Trial fitting before adhesive is applied"]],"application":{"q":"Why dry-assemble a frame?","options":["To check fit, squareness and alignment before gluing","To replace all measuring","To avoid using any appropriate clamps"],"answer":0,"why":"A dry fit reveals problems while adjustments are still possible. Follow the demonstrated workshop process."},"challenge":"Explain how you would check a rectangular frame for squareness and why this matters."},{"id":"woodwork-3","title":"Carcase construction","level":"National 4–5 foundations","pairs":[["Carcase","Box-like structure of a cabinet or similar item"],["Housing joint","Joint with one component located in a channel in another"],["Rebate","Step-shaped recess along an edge"],["Plywood","Board made from layers of veneer bonded with alternating grain directions"]],"application":{"q":"Why can a housing joint help locate a shelf?","options":["The channel positions and supports the shelf end","It makes the shelf impossible to measure","It removes all need for a suitable joint design"],"answer":0,"why":"A housing provides location and bearing area; its suitability still depends on loading and construction."},"challenge":"Sketch a box structure and justify a suitable joint for one corner."},{"id":"woodwork-4","title":"Machining and finishing knowledge","level":"National 4–5 foundations","pairs":[["Grain","Direction and arrangement of wood fibres"],["Sanding","Abrading a surface with progressively suitable abrasives"],["Finish","Coating or treatment affecting appearance or protection"],["Risk assessment","Consideration of hazards and suitable controls"]],"application":{"q":"What should happen before unfamiliar equipment is used?","options":["Teacher instruction, checks and permission under school procedures","Copy a video and start independently","Assume every machine has identical controls"],"answer":0,"why":"Online revision does not replace demonstration, authorisation or workshop safety procedures."},"challenge":"Explain how a finish should be selected for a product’s intended use; do not test substances without permission."}],"business":[{"id":"business-1","title":"Enterprise and business purpose","level":"BGE / National 4–5 foundations","pairs":[["Entrepreneur","Person organising an enterprise and taking business risks"],["Stakeholder","Person or group affected by or able to affect an organisation"],["Profit","Revenue minus costs over a period"],["Social enterprise","Business trading to pursue a social or environmental purpose"]],"application":{"q":"An enterprise earns £500 revenue and has £350 total costs. What is profit?","options":["£150","£850","£350"],"answer":0,"why":"Profit is revenue minus costs: £500 − £350 = £150. Revenue alone is not profit."},"challenge":"Identify two stakeholders in a fictional enterprise and explain a possible conflict between their aims."},{"id":"business-2","title":"Marketing","level":"National 5 / Higher foundations","pairs":[["Market research","Collection and analysis of information about customers and markets"],["Segmentation","Division of a market into groups with shared characteristics"],["Marketing mix","Combination of decisions such as product, price, place and promotion"],["USP","Distinctive feature used to differentiate an offering"]],"application":{"q":"A business surveys only its current followers about a new market. What is a limitation?","options":["The sample may not represent intended new customers","All online information is automatically false","A small logo invalidates every answer"],"answer":0,"why":"The sampling group may exclude non-customers and people with different preferences."},"challenge":"Recommend a research method for a new product and explain one limitation."},{"id":"business-3","title":"People and operations","level":"National 5 / Higher foundations","pairs":[["Recruitment","Process of attracting applicants for a role"],["Training","Development of skills and knowledge for work"],["Quality control","Checking outputs against standards"],["Productivity","Output relative to inputs over a period"]],"application":{"q":"Why can training improve productivity?","options":["Staff may perform tasks more accurately and efficiently","It guarantees all costs disappear","It means quality never needs checking"],"answer":0,"why":"Training can improve capability, but effects depend on relevance, implementation and other conditions."},"challenge":"Compare a quality check with preventing errors during the production process."},{"id":"business-4","title":"Finance and external influences","level":"National 5 / Higher foundations","pairs":[["Cash flow","Movement of money into and out of a business"],["Budget","Planned income or expenditure"],["Break-even","Point where total revenue equals total costs"],["External factor","Influence outside an organisation’s direct control"]],"application":{"q":"Can a profitable business still have a cash-flow problem?","options":["Yes; payments received and payments due can occur at different times","No; profit and cash are always identical","Only if it has no customers"],"answer":0,"why":"Profit is measured over a period, while timing of cash receipts and payments affects ability to pay bills."},"challenge":"Explain how an increase in a supplier’s prices might affect two business decisions."}],"administration":[{"id":"administration-1","title":"Organisation and customer service","level":"BGE / National 4–5 foundations","pairs":[["Agenda","Ordered list of business for a meeting"],["Minutes","Record of a meeting’s decisions and agreed actions"],["Deadline","Latest time by which a task should be completed"],["Customer service","Support provided to users or customers of a service"]],"application":{"q":"Which meeting record is most useful for follow-up?","options":["Actions with named responsibility and completion dates","A list of unrelated opinions only","An agenda presented as if it records decisions already made"],"answer":0,"why":"Minutes should make decisions and responsibilities clear; an agenda is a plan for the meeting."},"challenge":"Create a fictional action record with tasks, responsibilities and dates."},{"id":"administration-2","title":"Spreadsheets","level":"National 4–5 foundations","pairs":[["Cell reference","Address identifying a spreadsheet cell"],["Formula","Expression used to calculate a result"],["Absolute reference","Reference fixed when a formula is copied"],["Sort","Reordering records by specified values"]],"application":{"q":"Why might a tax-rate cell use an absolute reference?","options":["To keep the rate cell fixed when a formula is copied","To prevent any calculation","To make every row sort alphabetically"],"answer":0,"why":"A fixed reference keeps the shared parameter constant while other references can change."},"challenge":"Explain how to test a spreadsheet formula using a simple known example."},{"id":"administration-3","title":"Databases and information","level":"National 5 / Higher foundations","pairs":[["Record","Collection of fields about one item or person"],["Field","Single category of information within a record"],["Query","Request selecting or processing data using criteria"],["Validation","Check that data meets specified rules"]],"application":{"q":"Does validation guarantee that entered data is true?","options":["No; it checks rules, not every fact about the real world","Yes; any allowed entry must be correct","It only changes font size"],"answer":0,"why":"A plausible value can satisfy a rule and still be wrong. Verification and source checks remain important."},"challenge":"Design validation for fictional event data and explain a remaining possible error."},{"id":"administration-4","title":"Documents and digital communication","level":"National 5 / Higher foundations","pairs":[["Template","Reusable structure for a document"],["Mail merge","Combining a main document with records to create personalised outputs"],["Proofreading","Checking text and layout for errors"],["Access permission","Rule controlling who can view or change information"]],"application":{"q":"Before sending a merged document, what should be checked?","options":["Recipient fields, content, permissions and a preview of outputs","Only the colour of the title","Whether the file name is the longest possible"],"answer":0,"why":"A correct template can still merge the wrong fields or reach the wrong audience; checking outputs matters."},"challenge":"Use invented records to plan a mail merge, explaining how you would avoid accidental disclosure."}],"home-economics":[{"id":"home-economics-1","title":"Food safety and hygiene","level":"BGE / Practical Cookery foundations","pairs":[["Cross-contamination","Transfer of harmful microorganisms or allergens between foods or surfaces"],["Hand hygiene","Cleaning hands appropriately to reduce contamination"],["Use-by date","Date relating to the safety of a perishable food when stored as instructed"],["Best-before date","Date primarily relating to food quality"]],"application":{"q":"Raw chicken juice contacts ready-to-eat salad. What is the main concern?","options":["Cross-contamination","Improved flavour","A harmless change in presentation only"],"answer":0,"why":"Ready-to-eat food may not receive a cooking step to destroy microorganisms. Follow school food-safety procedures."},"challenge":"Explain how to organise a workspace to separate raw and ready-to-eat food; follow teacher guidance for all practical work."},{"id":"home-economics-2","title":"Nutrition and health","level":"BGE / Health and Food Technology foundations","pairs":[["Carbohydrate","Nutrient group that includes sugars and starches and provides energy"],["Protein","Nutrient needed for growth and repair among other functions"],["Fibre","Dietary component supporting normal bowel function"],["Balanced diet","Eating pattern providing suitable variety and proportions over time"]],"application":{"q":"Which approach best evaluates a meal’s nutritional balance?","options":["Consider ingredients, portions and the wider eating pattern","Judge only its colour","Assume one food supplies every nutrient needed"],"answer":0,"why":"Balance concerns the overall pattern and suitable quantities rather than a single “perfect” food."},"challenge":"Suggest one change to a fictional meal and explain a nutritional reason without making personal medical claims."},{"id":"home-economics-3","title":"Cookery skills and planning","level":"National 4–5 Practical Cookery foundations","pairs":[["Mise en place","Organising ingredients and equipment before preparation"],["Time plan","Sequence of tasks coordinated with available time"],["Simmering","Gentle cooking in liquid just below a vigorous boil"],["Evaluation","Judging a product against intended qualities"]],"application":{"q":"Two dishes must finish together. What should a time plan consider?","options":["Preparation, cooking, cooling and safe overlaps between tasks","Only the order of dish names","Start both at the last possible minute"],"answer":0,"why":"A coordinated plan considers task lengths and dependencies, while preserving safe working."},"challenge":"Write a teacher-approved preparation plan with one dependency and one appropriate parallel task."},{"id":"home-economics-4","title":"Food product development","level":"National 5 / Higher Health and Food Technology foundations","pairs":[["Design specification","Criteria a product is intended to meet"],["Sensory evaluation","Assessment of qualities such as flavour, texture and appearance"],["Consumer need","Requirement of the intended user group"],["Prototype","Trial version developed for testing"]],"application":{"q":"A product passes a taste test but breaches the specified budget. What follows?","options":["It needs further development against the full specification","It automatically meets every requirement","The budget can be ignored because taste is positive"],"answer":0,"why":"Evaluation checks multiple criteria; one successful quality does not prove the design meets all needs."},"challenge":"Design a fair sensory comparison using coded samples and suitable school procedures."}],"drama":[{"id":"drama-1","title":"Character and role","level":"BGE / Senior foundations","pairs":[["Character","Person represented within a drama"],["Role","Function or identity adopted in a dramatic situation"],["Motivation","Reason driving a character’s actions"],["Status","Relative social power or position in an interaction"]],"application":{"q":"A character says “I’m fine” while avoiding eye contact. What may this create?","options":["A contrast between spoken words and suggested feelings","Proof that every audience must interpret it identically","No meaning unless the character shouts"],"answer":0,"why":"Performance choices can suggest subtext; interpretation needs reference to context and specific evidence."},"challenge":"Perform a line in two contrasting ways and explain how voice and movement change its meaning."},{"id":"drama-2","title":"Voice and movement","level":"BGE / National 4–5 foundations","pairs":[["Pace","Speed of speech or action"],["Pause","Deliberate break in speech or action"],["Gesture","Movement communicating an idea or feeling"],["Proxemics","Use of distance and positioning between performers"]],"application":{"q":"How might increased distance between characters affect a scene?","options":["It can suggest tension or separation, depending on context","It always makes the characters friends","It removes the need for any other choices"],"answer":0,"why":"Physical relationships contribute to meaning, but effects depend on the situation and other performance choices."},"challenge":"Choose one moment and justify a precise vocal and a movement choice."},{"id":"drama-3","title":"Devising and production skills","level":"National 5 foundations","pairs":[["Stimulus","Starting point for creating drama"],["Convention","Recognisable dramatic technique or device"],["Blocking","Planned positioning and movement of performers"],["Cue","Signal for an action or technical change"]],"application":{"q":"Why record blocking and technical cues?","options":["To make rehearsals and performances coordinated and repeatable","To stop performers understanding the scene","To replace every rehearsal"],"answer":0,"why":"Shared records help performers and technical teams coordinate intentional choices."},"challenge":"Plan a short scene from a neutral stimulus, identifying intention, audience and one technical choice."},{"id":"drama-4","title":"Analysis and evaluation","level":"National 5 / Higher foundations","pairs":[["Dramatic intention","Meaning or impact a production aims to communicate"],["Audience response","How viewers interpret or react to performance"],["Evaluation","Supported judgement about effectiveness"],["Production concept","Overall interpretation guiding staging and design"]],"application":{"q":"Which evaluation is strongest?","options":["The narrow spotlight isolated the character, reinforcing the intended loneliness","The lights were good","Everyone definitely felt exactly the same"],"answer":0,"why":"Specific production evidence linked to intention supports a reasoned judgement; avoid assuming a universal response."},"challenge":"Evaluate one moment using a precise example, intended effect and possible improvement."}],"music":[{"id":"music-1","title":"Rhythm and metre","level":"BGE / Senior foundations","pairs":[["Beat","Regular underlying pulse"],["Rhythm","Pattern of note durations and silences"],["Tempo","Speed of the beat"],["Syncopation","Accent or emphasis away from expected strong beats"]],"application":{"q":"A performer changes tempo from 60 to 120 beats per minute. What happens?","options":["The beat rate doubles","Every note becomes twice as loud","The melody necessarily changes key"],"answer":0,"why":"Tempo measures beat rate, not loudness or pitch. Note values are interpreted relative to the beat."},"challenge":"Clap a rhythm at two tempos and explain what changes and what remains the same."},{"id":"music-2","title":"Melody and harmony","level":"BGE / National 4–5 foundations","pairs":[["Melody","Sequence of pitches heard as a line"],["Chord","Group of notes sounded together"],["Scale","Ordered collection of pitches"],["Interval","Distance in pitch between two notes"]],"application":{"q":"A melody moves from one note to its immediate neighbour in a scale. What movement is this?","options":["Stepwise movement","A large leap","A change of timbre only"],"answer":0,"why":"Stepwise motion uses neighbouring scale notes, while a leap skips over notes."},"challenge":"Create a short melody with both steps and leaps and describe its shape."},{"id":"music-3","title":"Texture, timbre and structure","level":"National 5 / Higher foundations","pairs":[["Timbre","Tone quality distinguishing sounds or instruments"],["Texture","Relationship and layering of musical parts"],["Dynamics","Levels and changes of loudness"],["Structure","Organisation of sections in a piece"]],"application":{"q":"A second independent melody enters against the first. What changes most directly?","options":["Texture","The definition of every instrument","The number of beats in every bar necessarily changes"],"answer":0,"why":"Adding an independent line changes the relationship between parts; tempo or metre need not change."},"challenge":"Compare two sections of a piece using evidence about texture, dynamics and instrumentation."},{"id":"music-4","title":"Performing and composing","level":"National 5 / Higher foundations","pairs":[["Rehearsal","Purposeful preparation to improve performance"],["Intonation","Accuracy of pitch in performance"],["Phrasing","Shaping musical ideas into meaningful units"],["Development","Transformation or extension of a musical idea"]],"application":{"q":"Which practice strategy best targets a difficult passage?","options":["Slow focused work on the passage, then gradual reintegration","Repeat the whole piece at full speed without listening","Only change the instrument’s colour"],"answer":0,"why":"Targeted rehearsal makes the problem and progress easier to identify, then tests learning in context."},"challenge":"Record a short appropriate performance, identify one specific improvement and compare a later attempt."}],"physical-education":[{"id":"physical-education-1","title":"Movement and skill development","level":"BGE / Senior foundations","pairs":[["Coordination","Organisation of body parts to perform movement effectively"],["Balance","Ability to maintain stability"],["Agility","Ability to change direction with control"],["Feedback","Information used to improve performance"]],"application":{"q":"A pupil practises a new movement inaccurately at full speed. What could help?","options":["Reduce complexity or speed, use feedback, then progress","Repeat the error faster","Remove every opportunity to practise"],"answer":0,"why":"Appropriate progression supports control and understanding before demands increase. Follow teacher instructions and individual adaptations."},"challenge":"Identify one skill, a suitable practice and one observable sign of improvement."},{"id":"physical-education-2","title":"Factors impacting performance","level":"National 5 / Higher foundations","pairs":[["Physical factor","Influence linked to bodily capabilities and demands"],["Mental factor","Influence involving thinking, attention or decisions"],["Emotional factor","Influence involving feelings and their management"],["Social factor","Influence involving relationships and interaction"]],"application":{"q":"A player loses concentration after a disagreement. What is the strongest explanation?","options":["Social and emotional factors may interact with mental focus","Only physical fitness can affect performance","Each performance factor is completely isolated"],"answer":0,"why":"Performance factors can interact; evidence should identify what happened rather than attach a label without explanation."},"challenge":"Explain how two factors can interact in a sporting situation using specific performance evidence."},{"id":"physical-education-3","title":"Planning improvement","level":"National 5 / Higher foundations","pairs":[["Baseline","Starting evidence collected before an intervention"],["SMART target","Goal made specific, measurable, achievable, relevant and time-bound"],["Progression","Planned increase in appropriate challenge"],["Monitoring","Checking evidence during a programme"]],"application":{"q":"Which target is most useful?","options":["Improve successful passes from 6/10 to 8/10 in a defined practice over four weeks","Get better at everything soon","Train as hard as possible without checking technique"],"answer":0,"why":"A defined measure and timescale make progress assessable; targets must also be realistic and appropriate."},"challenge":"Design a safe teacher-approved practice with a baseline, target and review point."},{"id":"physical-education-4","title":"Evaluating progress","level":"National 5 / Higher foundations","pairs":[["Validity","Extent to which a measure assesses what it is intended to assess"],["Reliability","Consistency of a measure under comparable conditions"],["Qualitative data","Descriptive information about performance"],["Quantitative data","Numerical information about performance"]],"application":{"q":"Why repeat a performance measure under similar conditions?","options":["To make comparison more reliable","To guarantee improvement regardless of performance","To remove the need for an appropriate test"],"answer":0,"why":"Comparable conditions reduce variation unrelated to the skill or factor being assessed."},"challenge":"Combine a numerical result with an observation, then explain one limitation before judging progress."}]},"careers":{"geography":{"area":"Animals, Land & Environment","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/2?isCareerAreaId=True","roles":["environmental management","geoscience","land and resource work"],"note":"Maps, fieldwork and evidence help you investigate places. Also explore planning, tourism and transport as related possibilities.","task":"Compare a field-based role with a data-based role. Which geographical skills appear in each?"},"care":{"area":"Social, Caring & Advisory Services","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/23?isCareerAreaId=True","roles":["social care","childcare","community support"],"note":"Understanding development, values and inequality helps you think about person-centred support. Professional roles can require specific qualifications and registration.","task":"Compare social care and social work. What training and responsibilities differ?"},"art":{"area":"Art & Design","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/4?isCareerAreaId=True","roles":["graphic design","illustration","three-dimensional design"],"note":"Your portfolio can show observation, development, experimentation and reasoned choices. Creative work includes both specialist practice and wider design roles.","task":"Compare a portfolio route with an apprenticeship or college route; record a requirement from the provider."},"modern-studies":{"area":"Law","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/17?isCareerAreaId=True","roles":["legal services","public policy","community advocacy"],"note":"Evaluating sources, weighing arguments and understanding institutions can support many routes. These are possible connections, not careers guaranteed by one subject.","task":"Compare a legal-services role with a public-service role and identify evidence of communication and judgement."},"maths":{"area":"Finance","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/11?isCareerAreaId=True","roles":["accountancy","actuarial work","risk and financial analysis"],"note":"Numeracy, modelling and checking assumptions are useful across finance, data, engineering and everyday decisions. Explore the exact mathematics required for each route.","task":"Compare two roles using numbers differently: what qualifications and tasks are listed?"},"english":{"area":"Communications & Media","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/7?isCareerAreaId=True","roles":["journalism","publishing","public relations"],"note":"Close reading, structuring an argument and writing for an audience can help in communication-intensive work. Combine these with subject interests and practical experience.","task":"Compare a writing-focused role with a spoken-communication role. Find two shared skills."},"spanish":{"area":"Arts, Social Sciences & Languages","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/5?isCareerAreaId=True","roles":["translation","interpreting","language teaching"],"note":"Spanish can combine with another specialism. Communication and cultural understanding also support exploration of tourism, business and international work.","task":"Compare interpreting with translation; identify the different tasks and training expectations."},"french":{"area":"Hospitality, Leisure & Tourism","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/15?isCareerAreaId=True","roles":["visitor services","tourism","hospitality"],"note":"French can be combined with a vocational or academic interest. Investigate where language skills add value rather than assuming every job needs the same level.","task":"Find one tourism role and one language-specialist role; compare how French could be used."},"history":{"area":"Arts, Social Sciences & Languages","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/5?isCareerAreaId=True","roles":["historical study","social sciences","teaching"],"note":"Enquiry, source evaluation and explaining change can support further study and many evidence-based careers. Heritage and archive work are additional directions to investigate.","task":"Find a heritage or research role and identify how it uses evidence and communication."},"rme":{"area":"Social, Caring & Advisory Services","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/23?isCareerAreaId=True","roles":["advice work","community education","caring services"],"note":"Ethical reasoning and fair consideration of viewpoints can support work with people. Explore training routes rather than assuming a subject alone qualifies you for a role.","task":"Find a role involving advice or support and explain why listening and impartiality matter."},"chemistry":{"area":"Science & Mathematics","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/21?isCareerAreaId=True","roles":["materials science","laboratory science","chemical analysis"],"note":"Accurate measurement, explanations and controlled investigation connect learning to scientific work. Engineering and manufacturing offer further routes to explore.","task":"Compare a laboratory technician route with a degree-based science route; check current requirements."},"physics":{"area":"Engineering","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/10?isCareerAreaId=True","roles":["electrical engineering","mechanical engineering","energy engineering"],"note":"Models, measurement and solving quantitative problems connect physics with design and technology. Explore technician, apprenticeship and university routes.","task":"Compare an engineering apprenticeship and a university course; record mathematics requirements from current listings."},"biology":{"area":"Animals, Land & Environment","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/2?isCareerAreaId=True","roles":["ecology","conservation","animal-related work"],"note":"Biological evidence helps explain organisms and environments. Health, biotechnology and laboratory work are other directions to investigate with your adviser.","task":"Compare a conservation role with a laboratory role. How do their working environments differ?"},"esol":{"area":"Arts, Social Sciences & Languages","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/5?isCareerAreaId=True","roles":["further language study","combined college courses","communication-rich work"],"note":"ESOL strengthens access to study and work across every sector. It does not limit your ambitions to language jobs; combine English development with your existing skills.","task":"Use the job-profile search for a career you already like. Note key vocabulary and any English-language requirements."},"graphic-communication":{"area":"Construction","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/9?isCareerAreaId=True","roles":["architectural technology","CAD","surveying"],"note":"Clear technical information, visualisation and accuracy connect classroom work with design and the built environment. Related roles may require additional technical qualifications.","task":"Compare a CAD role and a construction-design role; identify the outputs each produces."},"woodwork":{"area":"Construction","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/9?isCareerAreaId=True","roles":["carpentry and joinery","wood and timber work","furniture-related study"],"note":"Measuring, planning and making accurately can support craft and construction routes. Practical school learning is a starting point, not permission to use professional equipment.","task":"Compare a joinery apprenticeship with a furniture course and note one practical requirement for each."},"business":{"area":"Administration & Management","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/1?isCareerAreaId=True","roles":["business management","human resources","customer service"],"note":"Understanding customers, people, costs and decisions can support enterprise and organisational roles. Compare work-based learning with college and university routes.","task":"Find a business role and identify one task involving people, one involving information and one involving decisions."},"administration":{"area":"Administration & Management","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/1?isCareerAreaId=True","roles":["business administration","payroll","public-services administration"],"note":"Accuracy, organisation and digital communication support reliable services. Investigate different workplaces and the qualifications they ask for.","task":"Compare two administrative roles and identify which digital skills are shared."},"home-economics":{"area":"Hospitality, Leisure & Tourism","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/15?isCareerAreaId=True","roles":["hospitality","food service","events"],"note":"Planning, safe preparation, teamwork and evaluating a product connect practical learning to hospitality. Nutrition and food science are additional routes needing their own qualifications.","task":"Compare a professional cookery route with a food-science route; check which subjects and experience are required."},"drama":{"area":"Performing Arts","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/20?isCareerAreaId=True","roles":["acting","technical theatre","production"],"note":"Performance is one route among many. Collaboration, interpretation and production planning also connect with backstage and technical work.","task":"Compare an onstage and a backstage role; note training and portfolio or audition expectations."},"music":{"area":"Performing Arts","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/20?isCareerAreaId=True","roles":["performance","sound production","music-related production"],"note":"Listening, rehearsal, creating and collaborating can connect with performance and technical sound roles. Build evidence of your process as well as finished work.","task":"Compare a performing route with a sound-production route and identify evidence you could begin collecting."},"physical-education":{"area":"Sport","pathway":"https://www.planitplus.net/CareerAreas/DownloadResourceDocument/24?isCareerAreaId=True","roles":["coaching","sports development","fitness-related work"],"note":"Analysing performance, planning improvement and communicating feedback connect learning with sport and activity roles. Check qualifications, safeguards and age requirements for any placement.","task":"Compare coaching and sports-development work. Find how each supports participation as well as performance."}}};
